        result += f" {play['name']}: {format_currency(this_amount / 100)} ({perf['audience']} seats)\n"
        total_amount += this_amount

    result += f"Amount owed is {format_currency(total_amount / 100)}\n"
    result += f"You earned {volume_credits} credits\n"
    return result


def calculate_amount_for_play(play, audience):
    if play['type'] == "tragedy":
        this_amount = 40000
        if audience > 30:
            this_amount += 1000 * (audience - 30)
    elif play['type'] == "comedy":
        this_amount = 30000
        if audience > 20:
            this_amount += 10000 + 500 * (audience - 20)
        this_amount += 300 * audience
    else:
        raise ValueError(f"Unknown type: {play['type']}")
    return this_amount


def calculate_volume_credits(play, audience):
    volume_credits = max(audience - 30, 0)
    if play['type'] == "comedy":
        volume_credits += audience // 5
    return volume_credits


def format_currency(amount):
    return f"${amount:,.2f}"
